<script setup lang="ts">
const model=defineModel<string>({default:''})
const api=inject<any>('adminFetch'),error=ref(''),pending=ref(false),media=ref<any[]>([]),show=ref(false)
const props=withDefaults(defineProps<{label?:string}>(),{label:'Изображение'})
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;pending.value=true;error.value='';try{const body=new FormData();body.append('file',file);const result=await api('/api/admin/upload',{method:'POST',body});model.value=result.url}catch(e:any){error.value=e?.data?.message||'Не удалось загрузить изображение'}finally{pending.value=false;(e.target as HTMLInputElement).value=''}}
async function library(){error.value='';try{media.value=await api('/api/admin/media');show.value=!show.value}catch(e:any){error.value=e?.data?.message||'Не удалось открыть библиотеку'}}
</script>
<template><div class="space-y-2"><label class="block text-sm">{{label}}<input :value="model" readonly class="input mt-1 text-xs" aria-label="Адрес выбранного изображения"/></label><img v-if="model" :src="model" alt="Предпросмотр выбранного изображения" class="max-h-52 w-full rounded-lg object-contain"/><label class="block text-sm">Загрузить JPG, PNG или WebP до 8 МБ<input type="file" accept="image/jpeg,image/png,image/webp" class="mt-2 block max-w-full text-xs" :disabled="pending" @change="upload"/></label><p v-if="pending" role="status">Загружаем…</p><p v-if="error" role="alert" class="text-red-300">{{error}}</p><div class="flex flex-wrap gap-2"><button type="button" class="btn-ghost" @click="library">Библиотека</button><button v-if="model" type="button" class="btn-ghost" @click="model=''">Убрать изображение</button></div><div v-if="show" class="grid max-h-80 grid-cols-3 gap-2 overflow-y-auto"><button v-for="m in media" :key="m.key" type="button" class="rounded border border-white/20 p-1" aria-label="Выбрать изображение" @click="model=m.url;show=false"><img :src="m.url" :alt="m.alt||'Изображение библиотеки'" class="aspect-square w-full object-cover"/></button><p v-if="!media.length" class="col-span-3 text-ash">Загруженных изображений пока нет.</p></div></div></template>
